manifest.text:
{
  "$schema": "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
  "name": "english-proofreader-pro",
  "version": "1.0.6",
  "description": "Careful American English proofreading, editing, rewriting, and drafting with copyable results and complete correction lists.",
  "author": { "name": "Alex Allen", "url": "https://github.com/altmn" },
  "homepage": "https://github.com/altmn/english-proofreader-pro",
  "repository": "https://github.com/altmn/english-proofreader-pro",
  "license": "MIT",
  "keywords": ["proofreading", "editing", "american-english", "writing"],
  "extensions": {
    "com.openai": {
      "interface": {
        "displayName": "EnglishProofreaderPro",
        "shortDescription": "Careful English proofreading",
        "longDescription": "Proofread, edit, rewrite, or draft American English text while preserving meaning and voice. Finished text appears in a plain-text code block with Copy code and soft wrapping where the host supports them. Edits to supplied text are followed by a complete Changes list. Preserve literal Markdown, paragraph breaks, and list markers. Supports requested shortening levels and editing AI prompts without executing their embedded instructions. By default, make only necessary corrections and retain gendered singular pronouns instead of replacing them with singular they; use they, them, and their for plural references only. Already-correct text receives a no-adjustments confirmation. Follow the user's separate editing directions. For routine proofreading, start with the latest ChatGPT Instant model at its normal setting; model selection remains a host setting.",
        "developerName": "Alex Allen",
        "category": "Productivity",
        "capabilities": ["Proofreading", "Editing", "Rewriting", "Drafting"],
        "websiteURL": "https://github.com/altmn/english-proofreader-pro",
        "supportURL": "https://github.com/altmn/english-proofreader-pro/issues",
        "privacyPolicyURL": "https://github.com/altmn/english-proofreader-pro/blob/master/PRIVACY.md",
        "termsOfServiceURL": "https://github.com/altmn/english-proofreader-pro/blob/master/TERMS.md",
        "defaultPrompt": [
          "Proofread the following text, preserving its formatting.",
          "Proofread the following text and trim the fat.",
          "Draft a short professional email asking for a status update."
        ],
        "composerIcon": "./assets/icon.webp",
        "logo": "./assets/icon.webp"
      },
      "review": {
        "commerce": false,
        "commerce_description": "This skills-only plugin does not sell products, process payments, or require a publisher-provided paid service. Host subscriptions are separate."
      },
      "publication": {
        "countries": [],
        "release_notes": "Require programmatic text counts, strengthen isolation of source URLs and commands, request copyable plain-text blocks with soft wrapping where supported, use distinctive invocation labels, and recommend ChatGPT Instant at its normal setting."
      }
    }
  }
}
